                        (Z_to_bv 64 (P + 4096)) a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 8) (Z_to_bv 64 SZ) (Z_to_bv 64 (rz_size n))
                        (Z_to_bv 64 n) (Z_to_bv 64 INST) (Z_to_bv 64 B) (Z_to_bv 64 (0 + - (8))) (Z_to_bv 64 7) (Z_to_bv 64 T)
                        (Z_to_bv 64 1) t3 t4 t5 t6)
